-- Упражнения книги 19, глава 14 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 14, 'la14-netplan-merge', 0, 'func', 'Слияние файлов netplan', 'Напишите функцию netplan_merge(files): files - список троек [каталог, имя файла, конфигурация], где конфигурация - уже разобранный YAML (словарь вида {''network'': {...}}). Правила netplan generate. Учитываются только файлы, чьё имя заканчивается на .yaml, из каталогов /lib/netplan, /etc/netplan и /run/netplan (остальные каталоги и имена игнорируйте). Если одно и то же имя файла есть в нескольких каталогах, остаётся только файл из самого приоритетного: /run/netplan выше /etc/netplan, а он выше /lib/netplan; остальные одноимённые файлы отбрасываются целиком. Оставшиеся файлы обрабатываются по порядку имён (имена сравниваются как обычные строки, каталог не важен): поздний файл добавляется к накопленному результату. Слияние двух значений: два словаря сливаются по ключам рекурсивно по тем же правилам; два списка склеиваются (элементы нового добавляются в конец старого); во всех остальных случаях (числа, строки, булевы значения, разные типы) новое значение заменяет старое. Верните итоговую конфигурацию (пустой словарь, если файлов нет).', 'def netplan_merge(files):
    pass
', 'Сначала словарь имя -> (каталог, конфиг) с приоритетами, потом sorted(имена) и рекурсивная функция merge(a, b).', '{"func": "netplan_merge", "tests": [{"args": [[["/etc/netplan", "50-cloud-init.yaml", {"network": {"version": 2, "ethernets": {"enp1s0": {"dhcp4": true}}}}], ["/etc/netplan", "60-extra.yaml", {"network": {"ethernets": {"enp1s0": {"addresses": ["192.0.2.10/24"], "nameservers": {"addresses": ["1.1.1.1"]}}}}}]]], "expected": {"network": {"version": 2, "ethernets": {"enp1s0": {"dhcp4": true, "addresses": ["192.0.2.10/24"], "nameservers": {"addresses": ["1.1.1.1"]}}}}}}, {"args": [[["/etc/netplan", "50-cloud-init.yaml", {"network": {"version": 2, "ethernets": {"enp1s0": {"dhcp4": true}}}}], ["/run/netplan", "50-cloud-init.yaml", {"network": {"version": 2, "ethernets": {"enp1s0": {"addresses": ["10.9.0.2/24"]}}}}]]], "expected": {"network": {"version": 2, "ethernets": {"enp1s0": {"addresses": ["10.9.0.2/24"]}}}}}, {"args": [[["/etc/netplan", "01-a.yaml", {"network": {"version": 2, "ethernets": {"eth0": {"addresses": ["10.0.0.5/24"], "mtu": 1500}}}}], ["/etc/netplan", "02-b.yaml", {"network": {"ethernets": {"eth0": {"addresses": ["10.0.0.6/24"], "mtu": 9000}}}}]]], "expected": {"network": {"version": 2, "ethernets": {"eth0": {"addresses": ["10.0.0.5/24", "10.0.0.6/24"], "mtu": 9000}}}}}, {"args": [[["/etc/netplan", "9-y.yaml", {"network": {"renderer": "NetworkManager"}}], ["/etc/netplan", "10-x.yaml", {"network": {"version": 2, "renderer": "networkd"}}]]], "expected": {"network": {"version": 2, "renderer": "NetworkManager"}}}, {"args": [[["/lib/netplan", "00-base.yaml", {"network": {"version": 2, "ethernets": {"eth0": {"dhcp4": true}}}}], ["/etc/netplan", "00-base.yaml", {"network": {"version": 2, "ethernets": {"eth1": {"dhcp4": true}}}}], ["/etc/netplan", "50-cloud-init.yaml.bak", {"network": {"ethernets": {"eth9": {"dhcp4": true}}}}], ["/lib/netplan", "20-more.yaml", {"network": {"ethernets": {"eth1": {"dhcp4": false, "routes": [{"to": "default", "via": "10.0.0.1"}]}}}}]]], "expected": {"network": {"version": 2, "ethernets": {"eth1": {"dhcp4": false, "routes": [{"to": "default", "via": "10.0.0.1"}]}}}}}, {"args": [[["/etc/netplan", "10-a.yaml", {"network": {"ethernets": {"eth0": {"routes": [{"to": "10.1.0.0/16", "via": "10.0.0.2"}], "optional": true}}}}], ["/run/netplan", "20-b.yaml", {"network": {"ethernets": {"eth0": {"routes": [{"to": "10.2.0.0/16", "via": "10.0.0.3"}], "optional": false}}}}], ["/etc/netplan", "30-c.yaml", {"network": {"ethernets": {"eth0": {"optional": true}}}}]]], "expected": {"network": {"ethernets": {"eth0": {"routes": [{"to": "10.1.0.0/16", "via": "10.0.0.2"}, {"to": "10.2.0.0/16", "via": "10.0.0.3"}], "optional": true}}}}}, {"args": [[]], "expected": {}}, {"args": [[["/usr/lib/netplan", "10-a.yaml", {"network": {"version": 2}}]]], "expected": {}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 14, 'la14-netplan-networkd', 1, 'func', 'Из netplan в файл .network', 'Напишите функцию netplan_to_networkd(name, definition): name - идентификатор Ethernet-устройства в netplan, definition - его словарь. Верните текст файла .network, который построит упрощённая модель renderer''а networkd. Разделы идут в таком порядке и разделяются одной пустой строкой, текст заканчивается одним переводом строки; пустые разделы не пишутся. 1) [Match]: если есть match, то по порядку строки Name=<match.name>, MACAddress=<match.macaddress в нижнем регистре>, Driver=<match.driver> (только те, что заданы); если match нет - одна строка Name=<name>. 2) [Link] со строкой MTUBytes=<mtu>, если задан mtu. 3) [Network]: строка DHCP= со значением yes, если включены и dhcp4, и dhcp6, ipv4 - только dhcp4, ipv6 - только dhcp6, иначе no; затем строка Address=<адрес> на каждый элемент addresses; затем DNS=<адрес> на каждый nameservers.addresses; затем одна строка Domains= со словами nameservers.search через пробел, если список не пуст. 4) По одному разделу [Route] на каждый элемент routes, по порядку: Destination=<to>, где to равное default превращается в 0.0.0.0/0 (если в via есть двоеточие - в ::/0); затем Gateway=<via>, если via задан; затем Metric=<metric>, если metric задан. Поле on-link не моделируется. 5) [DHCPv4], если в dhcp4-overrides есть use-dns и/или route-metric: UseDNS=yes или no, затем RouteMetric=<число>.', 'def netplan_to_networkd(name, definition):
    pass
', 'Соберите список разделов, каждый - список строк, и в конце ''\n\n''.join(''\n''.join(s) ...) + ''\n''.', '{"func": "netplan_to_networkd", "tests": [{"args": ["enp1s0", {"dhcp4": true}], "expected": "[Match]\nName=enp1s0\n\n[Network]\nDHCP=ipv4\n"}, {"args": ["eth0", {"addresses": ["192.0.2.10/24", "2001:db8::10/64"], "routes": [{"to": "default", "via": "192.0.2.1", "metric": 100}], "nameservers": {"addresses": ["192.0.2.53", "9.9.9.9"], "search": ["example.org", "lan"]}}], "expected": "[Match]\nName=eth0\n\n[Network]\nDHCP=no\nAddress=192.0.2.10/24\nAddress=2001:db8::10/64\nDNS=192.0.2.53\nDNS=9.9.9.9\nDomains=example.org lan\n\n[Route]\nDestination=0.0.0.0/0\nGateway=192.0.2.1\nMetric=100\n"}, {"args": ["lan", {"match": {"name": "en*", "macaddress": "52:54:00:AB:CD:EF"}, "dhcp4": true, "dhcp6": true, "mtu": 9000}], "expected": "[Match]\nName=en*\nMACAddress=52:54:00:ab:cd:ef\n\n[Link]\nMTUBytes=9000\n\n[Network]\nDHCP=yes\n"}, {"args": ["wan", {"match": {"driver": "ixgbe"}, "addresses": ["203.0.113.2/30"], "routes": [{"to": "default", "via": "2001:db8::1"}, {"to": "10.8.0.0/16", "via": "203.0.113.1", "metric": 50, "on-link": true}]}], "expected": "[Match]\nDriver=ixgbe\n\n[Network]\nDHCP=no\nAddress=203.0.113.2/30\n\n[Route]\nDestination=::/0\nGateway=2001:db8::1\n\n[Route]\nDestination=10.8.0.0/16\nGateway=203.0.113.1\nMetric=50\n"}, {"args": ["eth1", {"dhcp6": true, "dhcp4-overrides": {"use-dns": false, "route-metric": 200}, "dhcp4": true}], "expected": "[Match]\nName=eth1\n\n[Network]\nDHCP=yes\n\n[DHCPv4]\nUseDNS=no\nRouteMetric=200\n"}, {"args": ["lo2", {}], "expected": "[Match]\nName=lo2\n\n[Network]\nDHCP=no\n"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 14, 'la14-nmcli-terse', 2, 'func', 'Разбор nmcli -t', 'Напишите функцию parse_nmcli_terse(text): text - вывод nmcli -t -f NAME,UUID,TYPE,DEVICE connection show. В режиме -t поля разделены двоеточием, а двоеточие и обратная косая черта внутри значения экранируются обратной косой чертой (\: и \\). Пустые и состоящие из пробелов строки пропускайте, как и строки, где после разбора получилось не ровно четыре поля. Для каждой остальной строки верните кортеж (name, uuid, type, device) с уже снятым экранированием: type 802-3-ethernet замените на ethernet, а 802-11-wireless на wifi (другие типы оставьте как есть); пустое device замените на None (профиль не активен). Порядок строк сохраняется.', 'def parse_nmcli_terse(text):
    pass
', 'Идите по символам: обратная косая черта берёт следующий символ как есть, неэкранированное двоеточие закрывает поле.', '{"func": "parse_nmcli_terse", "tests": [{"args": ["Wired connection 1:a1b2c3d4-0000-4000-8000-000000000001:802-3-ethernet:enp1s0\nlo:b2c3d4e5-0000-4000-8000-000000000002:loopback:lo\nOffice\\: VPN:c3d4e5f6-0000-4000-8000-000000000003:vpn:\nbr0:d4e5f6a7-0000-4000-8000-000000000004:bridge:br0\n"], "expected": [{"__tuple__": ["Wired connection 1", "a1b2c3d4-0000-4000-8000-000000000001", "ethernet", "enp1s0"]}, {"__tuple__": ["lo", "b2c3d4e5-0000-4000-8000-000000000002", "loopback", "lo"]}, {"__tuple__": ["Office: VPN", "c3d4e5f6-0000-4000-8000-000000000003", "vpn", null]}, {"__tuple__": ["br0", "d4e5f6a7-0000-4000-8000-000000000004", "bridge", "br0"]}]}, {"args": ["home-wifi:e5f6a7b8-0000-4000-8000-000000000005:802-11-wireless:wlp2s0\nback\\\\slash\\:x:f6a7b8c9-0000-4000-8000-000000000006:ethernet:eth1\n"], "expected": [{"__tuple__": ["home-wifi", "e5f6a7b8-0000-4000-8000-000000000005", "wifi", "wlp2s0"]}, {"__tuple__": ["back\\slash:x", "f6a7b8c9-0000-4000-8000-000000000006", "ethernet", "eth1"]}]}, {"args": ["\nbroken line:with:three\nok:00000000-0000-4000-8000-00000000000a:ethernet:eth0\ntoo:many:colons:in:this:line\n   \nbond0:00000000-0000-4000-8000-00000000000b:bond:bond0\n"], "expected": [{"__tuple__": ["ok", "00000000-0000-4000-8000-00000000000a", "ethernet", "eth0"]}, {"__tuple__": ["bond0", "00000000-0000-4000-8000-00000000000b", "bond", "bond0"]}]}, {"args": ["esc\\\\:00000000-0000-4000-8000-00000000000c:vlan:\n"], "expected": [{"__tuple__": ["esc\\", "00000000-0000-4000-8000-00000000000c", "vlan", null]}]}, {"args": [""], "expected": []}, {"args": ["x:y:ethernet:z"], "expected": [{"__tuple__": ["x", "y", "ethernet", "z"]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 14, 'la14-keyfile', 3, 'func', 'Профиль .nmconnection', 'Напишите функцию parse_keyfile(text): text - содержимое файла профиля NetworkManager в формате keyfile (ini: секции в квадратных скобках, строки ключ=значение; строки, начинающиеся с #, и пустые пропускайте; пробелы вокруг ключа и значения срезайте; повторный ключ в секции заменяет предыдущий). Верните словарь с ключами: id - connection.id (или ''''); type - connection.type, где 802-3-ethernet заменён на ethernet, а 802-11-wireless на wifi (или ''''); interface - connection.interface-name (или ''''); autoconnect - False, только если connection.autoconnect равно false (без учёта регистра), иначе True; method4 - ipv4.method (если ключа нет, ''auto''); addresses - список адресов из ключей addressN секции ipv4 (N - целое число, порядок по возрастанию N, а не по тексту), в каждом значении адрес/префикс идёт до первой запятой; gateway - значение ключа gateway секции ipv4, а если его нет или оно пустое - шлюз после запятой в первом по порядку addressN, где он указан, иначе ''''; dns - список адресов из ipv4.dns (разделитель ;, пустые элементы отбросить); routes - список кортежей (сеть, шлюз, метрика) из ключей routeN секции ipv4 в порядке возрастания N: значение сеть/префикс[,шлюз[,метрика]], отсутствующий шлюз - '''', отсутствующая метрика - None, метрика - целое число. Ключи вроде route1_options и dns-search не являются ни addressN, ни routeN.', 'def parse_keyfile(text):
    pass
', 'Соберите секции в словарь словарей; для addressN и routeN используйте re.fullmatch(r''address(\d+)'', ключ) и сортируйте по int.', '{"func": "parse_keyfile", "tests": [{"args": ["[connection]\nid=lan0\nuuid=3c2f9d52-7a3b-4c1e-9a55-0b1d2e3f4a5b\ntype=ethernet\ninterface-name=enp1s0\n\n[ethernet]\nmac-address=52:54:00:12:34:56\n\n[ipv4]\naddress1=10.0.0.5/24,10.0.0.1\ndns=1.1.1.1;9.9.9.9;\nmethod=manual\n\n[ipv6]\nmethod=disabled\n"], "expected": {"id": "lan0", "type": "ethernet", "interface": "enp1s0", "autoconnect": true, "method4": "manual", "addresses": ["10.0.0.5/24"], "gateway": "10.0.0.1", "dns": ["1.1.1.1", "9.9.9.9"], "routes": []}}, {"args": ["# generated by hand\n[connection]\nid=Wired connection 1\ntype=802-3-ethernet\nautoconnect=false\n\n[ipv4]\nmethod=auto\n"], "expected": {"id": "Wired connection 1", "type": "ethernet", "interface": "", "autoconnect": false, "method4": "auto", "addresses": [], "gateway": "", "dns": [], "routes": []}}, {"args": ["[connection]\nid=srv\ntype=ethernet\ninterface-name=eth0\nautoconnect=true\n\n[ipv4]\naddress2=192.168.50.7/24\naddress1=10.0.0.5/24,10.0.0.1\naddress10=172.16.0.9/16\ngateway=10.0.0.254\nroute2=192.168.0.0/16,10.0.0.9\nroute1=172.20.0.0/14,10.0.0.8,300\nroute1_options=mtu=1400\nroute3=10.99.0.0/16\ndns=8.8.8.8;\ndns-search=example.org;\nmethod=manual\n"], "expected": {"id": "srv", "type": "ethernet", "interface": "eth0", "autoconnect": true, "method4": "manual", "addresses": ["10.0.0.5/24", "192.168.50.7/24", "172.16.0.9/16"], "gateway": "10.0.0.254", "dns": ["8.8.8.8"], "routes": [{"__tuple__": ["172.20.0.0/14", "10.0.0.8", 300]}, {"__tuple__": ["192.168.0.0/16", "10.0.0.9", null]}, {"__tuple__": ["10.99.0.0/16", "", null]}]}}, {"args": ["[connection]\nid=dummy\ntype=dummy\n[ipv4]\nmethod=link-local\naddress1=169.254.1.1/16,\n"], "expected": {"id": "dummy", "type": "dummy", "interface": "", "autoconnect": true, "method4": "link-local", "addresses": ["169.254.1.1/16"], "gateway": "", "dns": [], "routes": []}}, {"args": [""], "expected": {"id": "", "type": "", "interface": "", "autoconnect": true, "method4": "auto", "addresses": [], "gateway": "", "dns": [], "routes": []}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 14, 'la14-networkd-pick', 4, 'func', 'Какой .network применится', 'Напишите функцию networkd_pick(units, iface): units - список троек [каталог, имя файла, match], iface - словарь свойств интерфейса с ключами name, mac, type, driver и, возможно, managed_by. match - словарь условий раздела [Match] (значение каждого - строка; отсутствие ключа означает отсутствие условия; пустой словарь подходит любому интерфейсу) либо None: так записан пустой файл или ссылка на /dev/null, которая маскирует одноимённый файл. Правила systemd-networkd. Учитываются только имена, оканчивающиеся на .network, из каталогов /etc/systemd/network, /run/systemd/network и /usr/lib/systemd/network (остальные игнорируйте). Файлы с одинаковым именем заменяют друг друга: остаётся файл из самого приоритетного каталога (/etc выше /run, а он выше /usr/lib); если оставшийся файл - маска (None), он не подходит ни одному интерфейсу. Файлы просматриваются по порядку имён (обычное сравнение строк), применяется первый файл, у которого выполнены все условия; остальные игнорируются, даже если подходят. Условия: Name, Type, Driver - список глоб-шаблонов оболочки (fnmatchcase) через пробел, условие верно, если подошёл хотя бы один; если значение начинается с ''!'', результат всего условия инвертируется; MACAddress - список адресов через пробел, сравнение без учёта регистра, без шаблонов. Интерфейс, у которого managed_by задан и не равен ''io.systemd.Network'', не подходит ни под один файл. Верните имя выбранного файла или '''', если подходящего нет.', 'def networkd_pick(units, iface):
    pass
', 'Сначала оставьте по одному файлу на имя (с приоритетом каталога), потом sorted(имена) и проверка условий; для ''!'' отрежьте первый символ и инвертируйте результат any(...).', '{"func": "networkd_pick", "tests": [{"args": [[["/etc/systemd/network", "20-wired.network", {"Name": "en*"}], ["/etc/systemd/network", "10-bond.network", {"Name": "bond0"}], ["/usr/lib/systemd/network", "99-default.network", {"Name": "*"}]], {"name": "enp1s0", "mac": "52:54:00:12:34:56", "type": "ether", "driver": "virtio_net"}], "expected": "20-wired.network"}, {"args": [[["/etc/systemd/network", "20-wired.network", {"Name": "en*"}], ["/etc/systemd/network", "10-bond.network", {"Name": "bond0"}], ["/usr/lib/systemd/network", "99-default.network", {"Name": "*"}]], {"name": "bond0", "mac": "02:00:00:00:00:01", "type": "ether", "driver": "bonding"}], "expected": "10-bond.network"}, {"args": [[["/etc/systemd/network", "20-wired.network", {"Name": "en*"}], ["/etc/systemd/network", "10-bond.network", {"Name": "bond0"}], ["/usr/lib/systemd/network", "99-default.network", {"Name": "*"}]], {"name": "lo", "mac": "", "type": "loopback", "driver": ""}], "expected": "99-default.network"}, {"args": [[["/etc/systemd/network", "20-wired.network", {"Name": "en*"}], ["/etc/systemd/network", "10-bond.network", {"Name": "bond0"}], ["/usr/lib/systemd/network", "99-default.network", {"Name": "*"}]], {"name": "enp1s0", "mac": "52:54:00:12:34:56", "type": "ether", "driver": "virtio_net", "managed_by": "io.systemd.Network"}], "expected": "20-wired.network"}, {"args": [[["/etc/systemd/network", "20-wired.network", {"Name": "en*"}], ["/etc/systemd/network", "10-bond.network", {"Name": "bond0"}], ["/usr/lib/systemd/network", "99-default.network", {"Name": "*"}]], {"name": "enp1s0", "mac": "52:54:00:12:34:56", "type": "ether", "driver": "virtio_net", "managed_by": "org.freedesktop.NetworkManager"}], "expected": ""}, {"args": [[["/etc/systemd/network", "10-not-wired.network", {"Name": "!en* lo"}], ["/etc/systemd/network", "20-all-ether.network", {"Type": "ether"}], ["/etc/systemd/network", "30-any.network", {}]], {"name": "lo", "mac": "", "type": "loopback", "driver": ""}], "expected": "30-any.network"}, {"args": [[["/etc/systemd/network", "10-not-wired.network", {"Name": "!en* lo"}], ["/etc/systemd/network", "20-all-ether.network", {"Type": "ether"}], ["/etc/systemd/network", "30-any.network", {}]], {"name": "enp1s0", "mac": "52:54:00:12:34:56", "type": "ether", "driver": "virtio_net"}], "expected": "20-all-ether.network"}, {"args": [[["/etc/systemd/network", "10-not-wired.network", {"Name": "!en* lo"}], ["/etc/systemd/network", "20-all-ether.network", {"Type": "ether"}], ["/etc/systemd/network", "30-any.network", {}]], {"name": "wlp3s0", "mac": "aa:bb:cc:dd:ee:ff", "type": "wlan", "driver": "iwlwifi"}], "expected": "10-not-wired.network"}, {"args": [[["/usr/lib/systemd/network", "10-vendor.network", {"Name": "enp1s0"}], ["/etc/systemd/network", "10-vendor.network", null], ["/run/systemd/network", "50-run.network", {"MACAddress": "52:54:00:12:34:56 52:54:00:12:34:57"}], ["/etc/systemd/network", "50-run.network.bak", {"Name": "*"}]], {"name": "enp1s0", "mac": "52:54:00:12:34:56", "type": "ether", "driver": "virtio_net"}], "expected": "50-run.network"}, {"args": [[["/usr/lib/systemd/network", "10-vendor.network", {"Name": "enp1s0"}], ["/etc/systemd/network", "10-vendor.network", null], ["/run/systemd/network", "50-run.network", {"MACAddress": "52:54:00:12:34:56 52:54:00:12:34:57"}], ["/etc/systemd/network", "50-run.network.bak", {"Name": "*"}]], {"name": "bond0", "mac": "02:00:00:00:00:01", "type": "ether", "driver": "bonding"}], "expected": ""}, {"args": [[["/run/systemd/network", "10-a.network", {"Name": "enp1s0"}], ["/etc/systemd/network", "10-a.network", {"Name": "eth*"}], ["/usr/lib/systemd/network", "05-drv.network", {"Driver": "virtio_net", "Type": "ether"}]], {"name": "enp1s0", "mac": "52:54:00:12:34:56", "type": "ether", "driver": "virtio_net"}], "expected": "05-drv.network"}, {"args": [[["/run/systemd/network", "10-a.network", {"Name": "enp1s0"}], ["/etc/systemd/network", "10-a.network", {"Name": "eth*"}], ["/usr/lib/systemd/network", "05-drv.network", {"Driver": "virtio_net", "Type": "ether"}]], {"name": "bond0", "mac": "02:00:00:00:00:01", "type": "ether", "driver": "bonding"}], "expected": ""}, {"args": [[["/etc/systemd/network", "10-a.network", {"MACAddress": "AA:BB:CC:DD:EE:FF"}], ["/etc/systemd/network", "20-b.network", {"Name": "wl* ww*", "Type": "!ether"}]], {"name": "wlp3s0", "mac": "aa:bb:cc:dd:ee:ff", "type": "wlan", "driver": "iwlwifi"}], "expected": "10-a.network"}, {"args": [[["/etc/systemd/network", "10-a.network", {"MACAddress": "AA:BB:CC:DD:EE:FF"}], ["/etc/systemd/network", "20-b.network", {"Name": "wl* ww*", "Type": "!ether"}]], {"name": "wlan0", "mac": "11:22:33:44:55:66", "type": "wlan", "driver": "ath9k"}], "expected": "20-b.network"}, {"args": [[["/etc/systemd/network", "10-a.network", {"MACAddress": "AA:BB:CC:DD:EE:FF"}], ["/etc/systemd/network", "20-b.network", {"Name": "wl* ww*", "Type": "!ether"}]], {"name": "enp1s0", "mac": "52:54:00:12:34:56", "type": "ether", "driver": "virtio_net"}], "expected": ""}, {"args": [[], {"name": "enp1s0", "mac": "52:54:00:12:34:56", "type": "ether", "driver": "virtio_net"}], "expected": ""}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 14, 'la14-ifcfg', 5, 'func', 'От ifcfg к keyfile', 'Старые дистрибутивы RHEL-семейства хранили профили в /etc/sysconfig/network-scripts/ifcfg-*; теперь по умолчанию используется keyfile. Напишите функцию ifcfg_to_keyfile(text): text - содержимое файла ifcfg (строки КЛЮЧ=значение; пустые строки и строки с # пропускайте; значение может быть в одинарных или двойных кавычках - снимите их; пробелы по краям срезайте). Верните словарь секций {секция: {ключ: строка}} по упрощённой модели миграции. Секция connection всегда есть: id - NAME, а если его нет или он пуст - DEVICE (или ''''); type - по TYPE: Ethernet -> ethernet, Bond -> bond, Bridge -> bridge, Vlan -> vlan, всё остальное и отсутствие -> ethernet; interface-name - DEVICE (ключ пишется, только если DEVICE непуст); autoconnect со значением ''false'', только если ONBOOT равно no без учёта регистра (по умолчанию ONBOOT=yes, ключ не пишется). Секция ethernet пишется, только если в ней что-то есть: mac-address - HWADDR как есть, mtu - MTU как есть (строкой). Секция ipv4 есть всегда: если BOOTPROTO равно dhcp (без учёта регистра) - method=auto; иначе если задан IPADDR - method=manual, address1=IPADDR/префикс (префикс - PREFIX, а если его нет, длина маски из NETMASK; если нет и его - 32) и gateway=GATEWAY, если GATEWAY задан; иначе method=disabled. Независимо от метода, если есть ключи DNS1, DNS2, ... (число после DNS любое, порядок по возрастанию числа, пустые значения пропускайте), добавьте dns - адреса через ; и с завершающим ;.', 'def ifcfg_to_keyfile(text):
    pass
', 'Длину маски даёт ipaddress.ip_network(''0.0.0.0/'' + маска).prefixlen; ключи DNS отбирайте через re.fullmatch(r''DNS\d+'', ключ).', '{"func": "ifcfg_to_keyfile", "tests": [{"args": ["TYPE=Ethernet\nBOOTPROTO=none\nDEVICE=eth0\nNAME=eth0\nONBOOT=yes\nIPADDR=192.0.2.10\nPREFIX=24\nGATEWAY=192.0.2.1\nDNS1=192.0.2.53\nDNS2=9.9.9.9\n"], "expected": {"connection": {"id": "eth0", "type": "ethernet", "interface-name": "eth0"}, "ipv4": {"method": "manual", "address1": "192.0.2.10/24", "gateway": "192.0.2.1", "dns": "192.0.2.53;9.9.9.9;"}}}, {"args": ["# Generated by anaconda\nTYPE=\"Ethernet\"\nBOOTPROTO=\"dhcp\"\nDEVICE=\"enp1s0\"\nNAME=\"System enp1s0\"\nONBOOT=\"no\"\nHWADDR=52:54:00:12:34:56\nMTU=9000\n"], "expected": {"connection": {"id": "System enp1s0", "type": "ethernet", "interface-name": "enp1s0", "autoconnect": "false"}, "ethernet": {"mac-address": "52:54:00:12:34:56", "mtu": "9000"}, "ipv4": {"method": "auto"}}}, {"args": ["DEVICE=bond0\nTYPE=Bond\nBOOTPROTO=none\nONBOOT=yes\nIPADDR=10.20.30.40\nNETMASK=255.255.254.0\nGATEWAY=10.20.30.1\nDNS2=8.8.4.4\nDNS1=10.20.30.2\nDNS10=1.1.1.1\n"], "expected": {"connection": {"id": "bond0", "type": "bond", "interface-name": "bond0"}, "ipv4": {"method": "manual", "address1": "10.20.30.40/23", "gateway": "10.20.30.1", "dns": "10.20.30.2;8.8.4.4;1.1.1.1;"}}}, {"args": ["DEVICE=eth1\nBOOTPROTO=none\nONBOOT=no\n"], "expected": {"connection": {"id": "eth1", "type": "ethernet", "interface-name": "eth1", "autoconnect": "false"}, "ipv4": {"method": "disabled"}}}, {"args": ["DEVICE=vlan100\nNAME=vlan100\nTYPE=Vlan\nVLAN=yes\nPHYSDEV=eth0\nBOOTPROTO=static\nIPADDR=''172.16.1.1''\n"], "expected": {"connection": {"id": "vlan100", "type": "vlan", "interface-name": "vlan100"}, "ipv4": {"method": "manual", "address1": "172.16.1.1/32"}}}, {"args": [""], "expected": {"connection": {"id": "", "type": "ethernet"}, "ipv4": {"method": "disabled"}}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 14, 'la14-conflicts', 6, 'func', 'Два владельца на одну карту', 'Напишите функцию find_conflicts(networkctl, nmcli, interfaces): три текста - вывод networkctl list (заголовок IDX LINK TYPE OPERATIONAL SETUP, затем строки с пятью словами и итоговая строка N links listed.), вывод nmcli device status (колонки DEVICE TYPE STATE CONNECTION, выровненные по заголовку; значения STATE и CONNECTION могут содержать пробелы) и файл /etc/network/interfaces. Определите, кто претендует на каждый интерфейс. networkd претендует, если SETUP равен configured или configuring. NetworkManager претендует, если STATE равен connected или начинается с connecting (connected (externally) - это конфигурация, сделанная не им, она не считается). ifupdown претендует, если имя указано в строке auto или allow-hotplug (после слова идёт одно или несколько имён) и для него есть хотя бы одна строка iface имя семейство метод с методом, отличным от manual; текст после # игнорируйте. Интерфейс lo игнорируйте полностью. Верните словарь {интерфейс: отсортированный список претендентов (имена networkd, NetworkManager, ifupdown)} только для интерфейсов, на которые претендуют двое или больше.', 'def find_conflicts(networkctl, nmcli, interfaces):
    pass
', 'Позиции колонок nmcli - re.finditer(r''\S+'', заголовок); значение колонки - срез строки от начала этой колонки до начала следующей.', '{"func": "find_conflicts", "tests": [{"args": ["IDX LINK   TYPE     OPERATIONAL SETUP\n  1 lo     loopback carrier     unmanaged\n  2 enp1s0 ether    routable    configured\n  3 enp2s0 ether    no-carrier  configuring\n  4 wlp3s0 wlan     off         unmanaged\n\n4 links listed.\n", "DEVICE  TYPE      STATE                   CONNECTION          \nenp1s0  ethernet  connected               Wired connection 1  \nenp2s0  ethernet  disconnected            --                  \nwlp3s0  wifi      connected               home-wifi           \nlo      loopback  connected (externally)  lo                  \n", "# This file describes the network interfaces\nsource /etc/network/interfaces.d/*\n\nauto lo\niface lo inet loopback\n\nauto enp1s0\niface enp1s0 inet dhcp\n\nallow-hotplug enp2s0\niface enp2s0 inet static\n    address 192.0.2.10/24\n    gateway 192.0.2.1\n"], "expected": {"enp1s0": ["NetworkManager", "ifupdown", "networkd"], "enp2s0": ["ifupdown", "networkd"]}}, {"args": ["IDX LINK   TYPE     OPERATIONAL SETUP\n  1 lo     loopback carrier     unmanaged\n  2 eth0   ether    routable    configured\n  3 eth1   ether    degraded    failed\n\n3 links listed.\n", "DEVICE  TYPE      STATE                                  CONNECTION  \neth0    ethernet  unmanaged                              --          \neth1    ethernet  connecting (getting IP configuration)  lan1        \nlo      loopback  unmanaged                              --          \n", "auto lo eth0 eth1\niface lo inet loopback\niface eth0 inet manual\niface eth1 inet6 auto   # comment\n#auto enp1s0\niface enp1s0 inet dhcp\n"], "expected": {"eth1": ["NetworkManager", "ifupdown"]}}, {"args": ["IDX LINK TYPE     OPERATIONAL SETUP\n  1 lo   loopback carrier     unmanaged\n\n1 links listed.\n", "DEVICE  TYPE      STATE      CONNECTION  \nlo      loopback  unmanaged  --          \n", ""], "expected": {}}, {"args": ["IDX LINK   TYPE     OPERATIONAL SETUP\n  1 lo     loopback carrier     unmanaged\n  2 enp1s0 ether    routable    configured\n  3 enp2s0 ether    no-carrier  configuring\n  4 wlp3s0 wlan     off         unmanaged\n\n4 links listed.\n", "DEVICE  TYPE      STATE      CONNECTION  \nlo      loopback  unmanaged  --          \n", ""], "expected": {}}, {"args": ["IDX LINK   TYPE     OPERATIONAL SETUP\n  1 lo     loopback carrier     unmanaged\n  2 enp1s0 ether    routable    configured\n  3 enp2s0 ether    no-carrier  configuring\n  4 wlp3s0 wlan     off         unmanaged\n\n4 links listed.\n", "DEVICE  TYPE      STATE                   CONNECTION          \nenp1s0  ethernet  connected               Wired connection 1  \nenp2s0  ethernet  disconnected            --                  \nwlp3s0  wifi      connected               home-wifi           \nlo      loopback  connected (externally)  lo                  \n", "auto lo eth0 eth1\niface lo inet loopback\niface eth0 inet manual\niface eth1 inet6 auto   # comment\n#auto enp1s0\niface enp1s0 inet dhcp\n"], "expected": {"enp1s0": ["NetworkManager", "networkd"]}}, {"args": ["IDX LINK   TYPE     OPERATIONAL SETUP\n  1 lo     loopback carrier     unmanaged\n  2 eth0   ether    routable    configured\n  3 eth1   ether    degraded    failed\n\n3 links listed.\n", "DEVICE  TYPE      STATE                                  CONNECTION  \neth0    ethernet  unmanaged                              --          \neth1    ethernet  connecting (getting IP configuration)  lan1        \nlo      loopback  unmanaged                              --          \n", "# This file describes the network interfaces\nsource /etc/network/interfaces.d/*\n\nauto lo\niface lo inet loopback\n\nauto enp1s0\niface enp1s0 inet dhcp\n\nallow-hotplug enp2s0\niface enp2s0 inet static\n    address 192.0.2.10/24\n    gateway 192.0.2.1\n"], "expected": {}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 14, 'la14-validate', 7, 'func', 'Проверка bond, bridge и VLAN', 'Напишите функцию validate_netplan(cfg): cfg - разобранный YAML netplan {''network'': {...}} с необязательными разделами ethernets, bonds, bridges, vlans (словари идентификатор -> определение; раздел может отсутствовать или быть None). Верните отсортированный список без повторов строк-ошибок по правилам проверки (точный текст важен). 1) version не равна 2 или отсутствует: ''network: version must be 2''. 2) Для каждого члена из interfaces бонда или моста, не определённого ни в одном из четырёх разделов: ''bonds.<id>: member <имя> is not defined'' (для моста ''bridges.<id>: ...''). 3) Режим бонда - parameters.mode (по умолчанию balance-rr); допустимы balance-rr, active-backup, balance-xor, broadcast, 802.3ad, balance-tlb, balance-alb, иначе ''bonds.<id>: unknown mode <режим>''. 4) Если режим допустим, но не 802.3ad, а в parameters есть lacp-rate: ''bonds.<id>: lacp-rate only applies to mode 802.3ad''. 5) Для каждого VLAN: id должен быть целым числом от 0 до 4094, иначе ''vlans.<id>: id <значение> out of range 0-4094'' (отсутствующий id печатается как None); link отсутствует - ''vlans.<id>: link is required'', не определён - ''vlans.<id>: link <имя> is not defined''. 6) Устройство, которое входит в interfaces двух и более различных бондов/мостов: ''<имя>: member of more than one aggregate (<идентификаторы по алфавиту через запятую и пробел>)''. 7) Устройство-член, у которого непустой addresses или включён dhcp4/dhcp6: ''<имя>: member of <первый по алфавиту агрегат> must not have addresses or dhcp''. Определение члена ищется среди всех четырёх разделов.', 'def validate_netplan(cfg):
    pass
', 'Сначала словарь всех определений и словарь член -> множество агрегатов, потом проверки по одной; в конце sorted(set(errs)).', '{"func": "validate_netplan", "tests": [{"args": [{"network": {"version": 2, "renderer": "networkd", "ethernets": {"eno1": {}, "eno2": {}, "eno3": {"dhcp4": true}}, "bonds": {"bond0": {"interfaces": ["eno1", "eno2"], "addresses": ["10.0.0.5/24"], "parameters": {"mode": "802.3ad", "lacp-rate": "fast", "mii-monitor-interval": 100}}}, "vlans": {"vlan100": {"id": 100, "link": "bond0"}}, "bridges": {"br0": {"interfaces": ["vlan100"]}}}}], "expected": []}, {"args": [{"network": {"version": 1, "ethernets": {"eno1": {"addresses": ["10.0.0.9/24"]}, "eno2": {}}, "bonds": {"bond0": {"interfaces": ["eno1", "eno2", "eno7"], "parameters": {"mode": "round-robin"}}}, "vlans": {"v1": {"id": 4095, "link": "bond0"}, "v2": {"id": 20}, "v3": {"id": 0, "link": "nope"}}}}], "expected": ["bonds.bond0: member eno7 is not defined", "bonds.bond0: unknown mode round-robin", "eno1: member of bond0 must not have addresses or dhcp", "network: version must be 2", "vlans.v1: id 4095 out of range 0-4094", "vlans.v2: link is required", "vlans.v3: link nope is not defined"]}, {"args": [{"network": {"version": 2, "ethernets": {"eno1": {}, "eno2": {"dhcp4": true}}, "bonds": {"bond0": {"interfaces": ["eno1"], "parameters": {"mode": "active-backup", "lacp-rate": "fast"}}}, "bridges": {"br0": {"interfaces": ["eno1", "eno2"]}, "br1": {"interfaces": ["eno2"]}}}}], "expected": ["bonds.bond0: lacp-rate only applies to mode 802.3ad", "eno1: member of more than one aggregate (bond0, br0)", "eno2: member of br0 must not have addresses or dhcp", "eno2: member of more than one aggregate (br0, br1)"]}, {"args": [{"network": {"ethernets": {"eno1": {}}, "vlans": {"v": {"id": 0, "link": "eno1"}}, "bonds": {"b": {"interfaces": ["eno1"], "parameters": {"lacp-rate": "slow"}}}}}], "expected": ["bonds.b: lacp-rate only applies to mode 802.3ad", "network: version must be 2"]}, {"args": [{"network": {}}], "expected": ["network: version must be 2"]}, {"args": [{}], "expected": ["network: version must be 2"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 14, 'la14-try-outcome', 8, 'func', 'Чем кончится netplan try', 'Напишите функцию try_outcome(old, new, ssh_addr, client, confirm_at, timeout): модель netplan try. old и new - конфигурации до и после изменения в виде {интерфейс: {''addresses'': [CIDR, ...], ''gateway'': адрес или отсутствует}}; ssh_addr - IPv4-адрес сервера, на который подключена ваша SSH-сессия (без префикса); client - IPv4-адрес вашего компьютера; confirm_at - секунда, на которой вы нажмёте подтверждение, или None, если не нажмёте; timeout - время ожидания в секундах. После применения new сессия остаётся жива, только если выполнены оба условия: ssh_addr входит (без префикса) в addresses какого-либо интерфейса new, и client либо лежит в подсети одного из адресов (addresses) любого интерфейса new, либо у какого-нибудь интерфейса new есть непустой gateway. Если сессия жива, confirm_at не None и confirm_at <= timeout, изменение подтверждено: верните кортеж (''kept'', confirm_at, копия new). Иначе настроенная сеть откатывается: верните (''rolled back'', timeout, копия old).', 'def try_outcome(old, new, ssh_addr, client, confirm_at, timeout):
    pass
', 'ipaddress.ip_interface(''192.0.2.10/24'').network даёт подсеть; ip_address(client) in подсеть проверяет принадлежность.', '{"func": "try_outcome", "tests": [{"args": [{"enp1s0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}}, {"enp1s0": {"addresses": ["192.0.2.10/24", "192.0.2.11/24"], "gateway": "192.0.2.1"}}, "192.0.2.10", "198.51.100.7", 30, 120], "expected": {"__tuple__": ["kept", 30, {"enp1s0": {"addresses": ["192.0.2.10/24", "192.0.2.11/24"], "gateway": "192.0.2.1"}}]}}, {"args": [{"enp1s0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}}, {"enp1s0": {"addresses": ["192.0.2.10/24", "192.0.2.11/24"], "gateway": "192.0.2.1"}}, "192.0.2.10", "198.51.100.7", 121, 120], "expected": {"__tuple__": ["rolled back", 120, {"enp1s0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}}]}}, {"args": [{"enp1s0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}}, {"enp1s0": {"addresses": ["198.51.100.10/24"], "gateway": "198.51.100.1"}}, "192.0.2.10", "198.51.100.7", 5, 120], "expected": {"__tuple__": ["rolled back", 120, {"enp1s0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}}]}}, {"args": [{"enp1s0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}}, {"enp1s0": {"addresses": ["192.0.2.10/24"]}}, "192.0.2.10", "198.51.100.7", 10, 120], "expected": {"__tuple__": ["rolled back", 120, {"enp1s0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}}]}}, {"args": [{"enp1s0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}}, {"enp1s0": {"addresses": ["192.0.2.10/24"]}}, "192.0.2.10", "192.0.2.77", 10, 120], "expected": {"__tuple__": ["kept", 10, {"enp1s0": {"addresses": ["192.0.2.10/24"]}}]}}, {"args": [{"enp1s0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}}, {"enp1s0": {"addresses": ["192.0.2.10/24", "192.0.2.11/24"], "gateway": "192.0.2.1"}}, "192.0.2.10", "198.51.100.7", null, 60], "expected": {"__tuple__": ["rolled back", 60, {"enp1s0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}}]}}, {"args": [{"enp1s0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}}, {"enp1s0": {"addresses": ["192.0.2.10/24", "192.0.2.11/24"], "gateway": "192.0.2.1"}}, "192.0.2.10", "198.51.100.7", 120, 120], "expected": {"__tuple__": ["kept", 120, {"enp1s0": {"addresses": ["192.0.2.10/24", "192.0.2.11/24"], "gateway": "192.0.2.1"}}]}}, {"args": [{"enp1s0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}}, {"br0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}, "enp1s0": {}}, "192.0.2.10", "203.0.113.5", 15, 30], "expected": {"__tuple__": ["kept", 15, {"br0": {"addresses": ["192.0.2.10/24"], "gateway": "192.0.2.1"}, "enp1s0": {}}]}}]}');
